import csv
import json
import math
import os

from pyscipopt import Model, quicksum

DATA_DIR = "/app/data"
OUT_DIR = "/app/submissions"


def read_csv(name):
    with open(os.path.join(DATA_DIR, name), newline="") as f:
        return list(csv.DictReader(f))


def main():
    with open(os.path.join(DATA_DIR, "config.json")) as f:
        config = json.load(f)

    printers = read_csv("printers.csv")
    materials = read_csv("materials.csv")
    orders = read_csv("orders.csv")
    eligibility = read_csv("printer_material_eligibility.csv")

    P = [r["printer_id"] for r in printers]
    M = [r["material_id"] for r in materials]
    O = [r["order_id"] for r in orders]

    avail = {r["printer_id"]: float(r["available_hours"]) for r in printers}
    cert = {r["printer_id"]: int(r["medical_certified"]) == 1 for r in printers}
    inv = {r["material_id"]: float(r["inventory_kg"]) for r in materials}
    mat_cost = {r["material_id"]: float(r["material_cost_per_kg"]) for r in materials}

    ord_mat = {}
    ord_req = {}
    ord_t = {}
    ord_w = {}
    ord_reg = {}
    ord_rev = {}
    ord_fill = {}
    for r in orders:
        oid = r["order_id"]
        ord_mat[oid] = r["material_id"]
        ord_req[oid] = int(r["requested_parts"])
        ord_t[oid] = float(r["print_hours_per_part"])
        ord_w[oid] = float(r["material_kg_per_part"])
        ord_reg[oid] = int(r["regulated"]) == 1
        ord_rev[oid] = float(r["revenue_per_part"])
        ord_fill[oid] = float(r["minimum_fill_rate"])

    elig = {}
    for r in eligibility:
        key = (r["printer_id"], r["material_id"])
        elig[key] = {
            "speed": float(r["speed_multiplier"]),
            "vcost": float(r["variable_cost_per_hour"]),
            "setup_h": float(r["setup_hours"]),
            "setup_c": float(r["setup_cost"]),
            "scrap": float(r["scrap_rate"]),
        }

    # Feasible (p, o) pairs: material eligible and (not regulated or printer certified)
    pairs = []
    for p in P:
        for o in O:
            m = ord_mat[o]
            if (p, m) not in elig:
                continue
            if ord_reg[o] and not cert[p]:
                continue
            pairs.append((p, o))

    # Derived per-pair parameters
    h_po = {}
    k_po = {}
    g_po = {}
    for (p, o) in pairs:
        m = ord_mat[o]
        e = elig[(p, m)]
        h_po[(p, o)] = ord_t[o] / e["speed"]
        k_po[(p, o)] = ord_w[o] * (1.0 + e["scrap"])
        g_po[(p, o)] = (
            ord_rev[o]
            - e["vcost"] * h_po[(p, o)]
            - mat_cost[m] * k_po[(p, o)]
        )

    # Minimum fill (integer, ceiling)
    min_fill = {o: int(math.ceil(ord_fill[o] * ord_req[o] - 1e-12)) for o in O}

    model = Model("additive_microfactory_order_planning")
    model.setParam("gaprel", 0.0005)

    time_limit = 300.0
    env_limit = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
    if env_limit is not None:
        try:
            time_limit = min(time_limit, float(env_limit))
        except ValueError:
            pass
    model.setParam("limits/time", time_limit)

    # Variables
    y = {}
    for (p, m), e in elig.items():
        y[(p, m)] = model.addVar(
            name="y_{}_{}".format(p, m), vtype="B", lb=0.0, ub=1.0, obj=-e["setup_c"]
        )

    x = {}
    for (p, o) in pairs:
        x[(p, o)] = model.addVar(
            name="x_{}_{}".format(p, o),
            vtype="I",
            lb=0.0,
            ub=float(ord_req[o]),
            obj=g_po[(p, o)],
        )

    # Objective: sum of variable objective coefficients (set via addVar obj)
    model.setObjective(0)
    # Rebuild objective explicitly to be safe
    obj_expr = quicksum(
        [
            g_po[(p, o)] * x[(p, o)] for (p, o) in pairs
        ]
        + [
            -elig[(p, m)]["setup_c"] * y[(p, m)] for (p, m) in y
        ]
    )
    model.setObjective(obj_expr, sense="maximize")

    # Setup linking
    for (p, o) in pairs:
        m = ord_mat[o]
        model.addCons(
            x[(p, o)] <= ord_req[o] * y[(p, m)],
            name="link_{}_{}".format(p, o),
        )

    # Printer capacity
    for p in P:
        prod_terms = [h_po[(p, o)] * x[(p, o)] for (pp, o) in pairs if pp == p]
        setup_terms = [
            elig[(p, m)]["setup_h"] * y[(p, m)] for (pp, m) in y if pp == p
        ]
        model.addCons(
            quicksum(setup_terms) + quicksum(prod_terms) <= avail[p],
            name="cap_{}".format(p),
        )

    # Material inventory
    for m in M:
        terms = [
            k_po[(p, o)] * x[(p, o)]
            for (p, o) in pairs
            if ord_mat[o] == m
        ]
        model.addCons(quicksum(terms) <= inv[m], name="mat_{}".format(m))

    # Demand upper bound and minimum fill per order
    for o in O:
        terms = [x[(p, o)] for (p, oo) in pairs if oo == o]
        model.addCons(quicksum(terms) <= ord_req[o], name="dem_{}".format(o))
        model.addCons(quicksum(terms) >= min_fill[o], name="fill_{}".format(o))

    model.optimize()

    status = model.getStatus()
    nsols = model.getNSols()
    print("Solver status:", status)
    print("Number of solutions:", nsols)

    best = model.getBestSol()
    obj_val = None
    if best is not None:
        obj_val = model.getObjVal()
        print("Objective value:", obj_val)

    # Extract solution
    sol_y = {}
    for (p, m), var in y.items():
        val = model.getVal(var)
        sol_y[(p, m)] = 1 if val > 0.5 else 0

    sol_x = {}
    for (p, o), var in x.items():
        val = model.getVal(var)
        sol_x[(p, o)] = int(round(val))

    # Validation
    tol = 1e-5
    ok = True

    for p in P:
        hours = sum(
            elig[(p, m)]["setup_h"] * sol_y[(p, m)] for (pp, m) in y if pp == p
        ) + sum(
            h_po[(p, o)] * sol_x[(p, o)] for (pp, o) in pairs if pp == p
        )
        if hours > avail[p] + tol:
            ok = False
            print("VIOLATION printer capacity", p, hours, avail[p])

    for m in M:
        kg = sum(
            k_po[(p, o)] * sol_x[(p, o)]
            for (p, o) in pairs
            if ord_mat[o] == m
        )
        if kg > inv[m] + tol:
            ok = False
            print("VIOLATION material inventory", m, kg, inv[m])

    for o in O:
        total = sum(sol_x[(p, o)] for (p, oo) in pairs if oo == o)
        if total > ord_req[o] + tol:
            ok = False
            print("VIOLATION demand", o, total, ord_req[o])
        if total + tol < min_fill[o]:
            ok = False
            print("VIOLATION fill", o, total, min_fill[o])

    for (p, o), val in sol_x.items():
        m = ord_mat[o]
        if val > 0 and sol_y[(p, m)] != 1:
            ok = False
            print("VIOLATION setup link", p, o)

    print("Validation passed:", ok)

    # Write solution
    os.makedirs(OUT_DIR, exist_ok=True)
    out_path = os.path.join(OUT_DIR, "solution.csv")
    with open(out_path, "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["row_type", "printer_id", "material_id", "order_id", "value"])
        for (p, m) in sorted(sol_y.keys()):
            if sol_y[(p, m)] == 1:
                w.writerow(["setup", p, m, "", "1"])
        for (p, o) in sorted(sol_x.keys()):
            if sol_x[(p, o)] > 0:
                w.writerow(
                    ["produce", p, ord_mat[o], o, str(sol_x[(p, o)])]
                )
    print("Wrote", out_path)

    # Free model
    model.free()


if __name__ == "__main__":
    main()
